<script setup lang="ts">
import {ref,watch} from 'vue'
import Icon from './Icon.vue'
import type {QuotaState} from './types'
const props=defineProps<{quota:QuotaState;busy:string}>()
const emit=defineEmits<{action:[method:string,params:Record<string,unknown>,message:string];error:[message:string]}>()
let stored='';try{stored=localStorage.getItem('ai-link-shared-endpoint') || ''}catch{}
const shared=ref(props.quota.control?.scope==='shared'),endpoint=ref(stored),credential=ref<{ref:string;name:string}|null>(null)
watch(()=>props.quota.control?.scope,value=>{if(props.quota.connected)shared.value=value==='shared'})
watch(endpoint,value=>{try{localStorage.setItem('ai-link-shared-endpoint',value)}catch{}})
async function chooseCredential(){try{credential.value=await window.aiLink.chooseCodexCredential() || credential.value}catch(error){emit('error',String(error))}}
function connect(){emit('action','quota.connect',{shared:shared.value,...(shared.value&&endpoint.value.trim()?{endpoint:endpoint.value.trim(),...(credential.value?{tokenRef:credential.value.ref}:{})}:{})},'Codex 已连接，请读取并接入需要守护的已有对话。')}
</script>
<template><section class="codex-connection"><section class="panel account-panel"><div class="account-identity"><span class="account-logo"><Icon name="terminal" :size="25"/></span><div><strong>Codex {{ quota.plan?`· ${quota.plan.toUpperCase()}`:'账户连接' }}</strong><span>{{ quota.connected?(quota.enabled?'额度守护已开启':'已连接，守护尚未开启'):'连接已有对话所在的 Codex 服务' }}</span></div></div><div class="account-actions"><label class="sr-only" for="connection-mode">连接范围</label><select id="connection-mode" v-model="shared" :disabled="quota.connected||!!busy"><option :value="false">本地历史接入</option><option :value="true">共享现有服务</option></select><button v-if="!quota.connected" class="btn primary" :disabled="!!busy" @click="connect"><Icon :name="busy==='quota.connect'?'refresh':'link'" :class="{spinning:busy==='quota.connect'}"/>连接 Codex</button><template v-else><button class="icon-button" aria-label="刷新额度" title="刷新额度" :disabled="!!busy" @click="emit('action','quota.refresh',{},'额度与对话状态已刷新。')"><Icon name="refresh" :class="{spinning:busy==='quota.refresh'}"/></button><button class="btn secondary" :disabled="!!busy" @click="emit('action','quota.disconnect',{},'已断开，守护已关闭。')">断开</button></template></div></section><div v-if="shared" class="panel shared-endpoint"><label class="field-label" for="shared-endpoint">本机共享服务地址<span>留空时检测默认共享接口</span></label><div class="shared-fields"><input id="shared-endpoint" v-model="endpoint" maxlength="200" placeholder="ws://127.0.0.1:4500" :disabled="quota.connected||!!busy" spellcheck="false"><button class="btn secondary" :disabled="quota.connected||!!busy||!endpoint" @click="chooseCredential"><Icon name="shield" :size="15"/>{{ credential?credential.name:'选择连接凭据（可选）' }}</button></div><p>要控制正在运行的已有对话，AI Link 必须连接到该对话使用的同一共享服务。独立桌面进程没有开放接口时，不能直接接管。连接凭据仅在本机读取，不显示 token。</p></div><p v-else class="connection-scope"><Icon name="info" :size="14"/>本地历史可接入已释放的对话；仍被其他 Codex 进程占用的目标会被拒绝，不会显示为已接管。</p></section></template>
<style scoped>
.codex-connection{display:grid;gap:12px}.shared-endpoint{padding:20px 23px}.shared-endpoint>.field-label{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.shared-fields{display:flex;gap:12px;align-items:center;margin:10px 0}.shared-fields input{flex:1;min-width:0;background:var(--surface-input);color:var(--text);border:1px solid var(--line);border-radius:9px;padding:11px 12px;font-size:12px}.shared-fields .btn{max-width:260px;overflow:hidden;text-overflow:ellipsis}.shared-endpoint p,.connection-scope{font-size:11px;line-height:1.9;color:var(--muted)}.connection-scope{display:flex;align-items:flex-start;gap:7px;padding:0 3px}.connection-scope svg{margin-top:4px}@media(max-width:700px){.shared-fields{flex-direction:column;align-items:stretch}.shared-fields .btn{max-width:none}.shared-endpoint{padding:18px}}
</style>
